// F123: the v7 entry fingerprint is computed in three places: the browser
// (src/lib/entryFingerprint.js), the Vercel route (server/deskBrief.mjs) and
// the desk-brief Edge Function (supabase/functions/_shared/entryFingerprint.ts),
// which keys the stored record brief by it. The fixture was generated by the
// server copy; the Deno test asserts the same file, so no copy can drift.
import { describe, expect, it } from 'vitest';
import fixture from './__fixtures__/entryFingerprint.json';
import { entryFingerprint as serverFingerprint } from '../../server/deskBrief.mjs';
import { entryFingerprintSha } from './entryFingerprint.js';
import { entryFingerprintSha as reexported } from './deskBrief.js';

describe('entry fingerprint parity', () => {
  it('reproduces every fixture case in the browser copy', async () => {
    expect(fixture.length).toBeGreaterThanOrEqual(8);
    for (const c of fixture) expect(await entryFingerprintSha(c.row, c.feature, c.tier), c.note).toBe(c.sha);
  });

  it('matches the server copy, and deskBrief.js still exports the same function', async () => {
    for (const c of fixture) expect(serverFingerprint(c.row, c.feature, c.tier), c.note).toBe(c.sha);
    expect(reexported).toBe(entryFingerprintSha);
  });

  it('changes when a field changes and ignores internal keys', async () => {
    const row = { title: 'Port', status: 'Open' };
    const a = await entryFingerprintSha(row, 'Infra', 'global');
    expect(await entryFingerprintSha({ ...row, status: 'Closed' }, 'Infra', 'global')).not.toBe(a);
    expect(await entryFingerprintSha({ ...row, __rowIndex: 4 }, 'Infra', 'global')).toBe(a);
    expect(await entryFingerprintSha(row, 'Infra', 'law')).not.toBe(a);
  });
});
